'use client'
/** Progress: the MATRIX card `ui-progress` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-progress')!

export type MatrixProgressProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixProgress(props: MatrixProgressProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
